function savePrefs(p){try{localStorage.setItem(PREF_KEY,JSON.stringify(p))}catch(e){}}
function applyPrefs(){const p=prefs();document.body.dataset.worldMotion=p.motion||"full";document.body.dataset.worldGraphics=p.graphics||"standard";document.body.dataset.worldText=p.text||"standard";if(p.controls){try{localStorage.setItem("escie_world_control_mode",p.controls)}catch(e){}}if(p.display==="handheld"&&typeof setHandheld==="function")setHandheld(true);else if(p.display==="device"&&typeof deviceMode==="function")deviceMode();if(p.orientation==="landscape"&&screen.orientation?.lock)screen.orientation.lock("landscape").catch(()=>{});if(p.orientation==="portrait"&&screen.orientation?.lock)screen.orientation.lock("portrait").catch(()=>{});}
function feedback(kind){const p=prefs();if(p.vibration==="off")return;if(kind==="select"||kind==="discover"){try{navigator.vibrate?.(kind==="discover"?[18,25,28]:10)}catch(e){}}}
const LIFE_KEY="escie_world_life_v1";
const LIFE_DEFAULT={hunger:82,energy:78,health:100,stress:12,social:35,money:40,reputation:0,status:"UNKNOWN",path:"UNDEFINED",time_minutes:720,day:1,neighbourhood:"PARC-EXTENSION"};
function getLife(){try{return Object.assign({},LIFE_DEFAULT,JSON.parse(localStorage.getItem(LIFE_KEY)||"{}"))}catch(e){return Object.assign({},LIFE_DEFAULT)}}
function saveLife(l){try{localStorage.setItem(LIFE_KEY,JSON.stringify(l))}catch(e){}}
function lifeLabel(v){return Math.max(0,Math.min(100,Math.round(v)))}
function updateLife(delta={}){const l=getLife();Object.keys(delta).forEach(k=>{if(typeof l[k]==="number")l[k]+=delta[k]});l.hunger=lifeLabel(l.hunger);l.energy=lifeLabel(l.energy);l.health=lifeLabel(l.health);l.stress=lifeLabel(l.stress);l.social=lifeLabel(l.social);l.money=Math.max(0,Math.round(l.money));saveLife(l);return l}
function lifeMenu(){let el=document.getElementById("world-life");if(!el){el=document.createElement("section");el.id="world-life";el.className="world-life";el.hidden=true;el.innerHTML='<div class="life-panel" role="dialog" aria-modal="true" aria-label="Life status"><div class="life-head"><div><span class="world-kicker">PLAYER SIMULATION</span><h2>LIFE</h2></div><button data-life-close class="system-close">CLOSE</button></div><div class="life-grid"><div class="life-stat"><strong>HUNGER</strong><span data-life-hunger></span><div class="life-bar"><i data-life-hunger-bar></i></div></div><div class="life-stat"><strong>ENERGY</strong><span data-life-energy></span><div class="life-bar"><i data-life-energy-bar></i></div></div><div class="life-stat"><strong>HEALTH</strong><span data-life-health></span><div class="life-bar"><i data-life-health-bar></i></div></div><div class="life-stat"><strong>STRESS</strong><span data-life-stress></span><div class="life-bar"><i data-life-stress-bar></i></div></div><div class="life-stat"><strong>SOCIAL</strong><span data-life-social></span><div class="life-bar"><i data-life-social-bar></i></div></div><div class="life-stat"><strong>MONEY</strong><span data-life-money></span></div><div class="life-stat"><strong>REPUTATION</strong><span data-life-reputation></span></div><div class="life-stat"><strong>SOCIAL STATUS</strong><span data-life-status></span></div><div class="life-stat"><strong>CURRENT PATH</strong><span data-life-path></span></div><div class="life-stat"><strong>LOCATION</strong><span data-life-location></span></div></div><div class="life-note">THE WORLD does not assign your identity. Your repeated choices, relationships, money, movement and consequences gradually shape the path.</div></div>';document.body.appendChild(el);el.querySelector("[data-life-close]").onclick=()=>el.hidden=true}const l=getLife();["hunger","energy","health","stress","social"].forEach(k=>{el.querySelector("[data-life-"+k+"]").textContent=lifeLabel(l[k])+"%";el.querySelector("[data-life-"+k+"-bar]").style.width=lifeLabel(l[k])+"%"});el.querySelector("[data-life-money]").textContent="$"+l.money;el.querySelector("[data-life-reputation]").textContent=String(l.reputation);el.querySelector("[data-life-status]").textContent=l.status;el.querySelector("[data-life-path]").textContent=l.path;el.querySelector("[data-life-location]").textContent=l.neighbourhood;el.hidden=false}
document.querySelector("[data-life]")?.addEventListener("click",lifeMenu);
if(!localStorage.getItem(LIFE_KEY))saveLife(LIFE_DEFAULT);
